def parse_pairs(lines):
    result = {}
    for line in lines:
        if not line.strip():
            continue
        if '=' not in line:
            raise ValueError('missing =')
        parts = line.split('=', 1)
        key = parts[0].strip()
        value = parts[1].strip()
        if not key:
            raise ValueError('empty key')
        result[key] = value
    return result

